#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(terra);library(sf);library(exactextractr);library(data.table);library(yaml);library(future.apply)})
a<-commandArgs(trailingOnly=TRUE);cfg<-read_yaml(ifelse(length(a),a[1],"config.yml"));dir.create(dirname(cfg$paths$output_csv),recursive=TRUE,showWarnings=FALSE);dir.create(cfg$paths$checkpoint_dir,recursive=TRUE,showWarnings=FALSE)
cat<-fread(cfg$paths$raster_catalog);b<-st_read(cfg$paths$boundaries,layer=cfg$paths$boundary_layer,quiet=TRUE)
stopifnot(all(c("unit_code","unit_name","spatial_system","level_code")%in%names(b)))
masks<-list(whole_boundary=NULL,cropland=rast(cfg$paths$cropland_mask),rainfed_cropland=rast(cfg$paths$rainfed_mask),irrigated_cropland=rast(cfg$paths$irrigated_mask))
statfun<-function(d){vc<-setdiff(names(d),c("coverage_fraction","area"))[1];ok<-is.finite(d[[vc]])&is.finite(d$coverage_fraction)&is.finite(d$area);x<-d[[vc]][ok];w<-d$coverage_fraction[ok]*d$area[ok];if(!length(x)||sum(w)==0)return(data.table(value_mean=NA,value_sd=NA,value_min=NA,value_max=NA,p10=NA,p50=NA,p90=NA,valid_area_km2=0,valid_pixel_count=0));mu<-weighted.mean(x,w);q<-quantile(x,c(.1,.5,.9),na.rm=TRUE);data.table(value_mean=mu,value_sd=sqrt(weighted.mean((x-mu)^2,w)),value_min=min(x),value_max=max(x),p10=q[1],p50=q[2],p90=q[3],valid_area_km2=sum(w),valid_pixel_count=length(x))}
process<-function(i){row<-cat[i];cp<-file.path(cfg$paths$checkpoint_dir,paste0("asset_",i,".rds"));if(file.exists(cp)&&!cfg$processing$overwrite)return(readRDS(cp));r<-rast(row$file);bb<-st_transform(b,crs(r));ans<-rbindlist(lapply(names(masks),function(ac){z<-r;if(!is.null(masks[[ac]])){mk<-project(masks[[ac]],r,method="near");z<-mask(r,mk,maskvalues=0,updatevalue=NA)};ee<-exact_extract(z,bb,include_area=TRUE,progress=FALSE);rbindlist(lapply(seq_along(ee),function(j){s<-statfun(ee[[j]]);s[,`:=`(unit_code=bb$unit_code[j],unit_name=bb$unit_name[j],spatial_system=bb$spatial_system[j],level_code=bb$level_code[j],area_class=ac)]}))}));ans[,`:=`(variable=row$variable,dataset_type=row$dataset_type,scenario=row$scenario,model=row$model,year=as.integer(row$year),month=as.integer(row$month),temporal_scale=row$temporal_scale,source_asset=row$file)];saveRDS(ans,cp);ans}
plan(multisession,workers=cfg$processing$workers);out<-rbindlist(future_lapply(seq_len(nrow(cat)),process,future.seed=TRUE),fill=TRUE);fwrite(out,cfg$paths$output_csv);message("Wrote ",nrow(out)," aggregate records")
